namespace Demo.Plugin.Services.Logging
{
    public class HostLogRepository
    {
        private readonly string _connectionString;

        public HostLogRepository(string connectionString)
        {
            _connectionString = connectionString;
        }

        public async Task<List<HostLogEntry>> QueryAsync(int pageSize)
        {
            const string sql = @"SELECT * FROM BZExtHostLogs ORDER BY Timestamp DESC
                                 OFFSET 0 ROWS FETCH NEXT @PageSize ROWS ONLY";

            using var connection = new SqlConnection(_connectionString);
            var logs = await connection.QueryAsync<HostLogEntry>(sql, new { PageSize = pageSize });
            return logs.AsList();
        }
    }
}

