using System.Data;
using Dapper;
using Microsoft.Data.SqlClient;

namespace Demo.Plugin.Features.Config
{
    public class ConfigRepository
    {
        private readonly string _connectionString;
        public ConfigRepository(string connectionString) { _connectionString = connectionString; }

        // Tabla DemoConfigurations: UpdatedAt es datetime2(7) (ver database/001_CreateConfig.sql).
        public async Task<bool> UpdateValueAsync(int id, string? value, DateTime expectedUpdatedAt)
        {
            const string sql = @"
                UPDATE [dbo].[DemoConfigurations]
                SET SettingValue = @Value, UpdatedAt = GETUTCDATE()
                WHERE Id = @Id AND UpdatedAt = @ExpectedUpdatedAt";

            var parameters = new DynamicParameters();
            parameters.Add("Id", id);
            parameters.Add("Value", value);
            parameters.Add("ExpectedUpdatedAt", expectedUpdatedAt);

            using var connection = new SqlConnection(_connectionString);
            return await connection.ExecuteAsync(sql, parameters) > 0;
        }
    }
}

